import React, { useState, useEffect } from 'react';

function HealthAssessment() {
  const [username, setUsername] = useState('');
  const [ageGroup, setAgeGroup] = useState('');
  const [gender, setGender] = useState('');
  const [submitted, setSubmitted] = useState(false);

  // Get username from localStorage
  useEffect(() => {
    const user = JSON.parse(localStorage.getItem('user') || '{}');
    setUsername(user.username || 'User');
  }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    setSubmitted(true);
  };

  return (
    <div style={styles.container}>
      <h1 style={styles.heading}>🩺 Health Assessment</h1>
      <p style={styles.text}>Hello, <strong>{username}</strong>! Please answer the questions below.</p>

      {!submitted ? (
        <form onSubmit={handleSubmit} style={styles.form}>
          <div style={styles.field}>
            <label>Age Group:</label>
            <select
              value={ageGroup}
              onChange={(e) => setAgeGroup(e.target.value)}
              style={styles.select}
            >
              <option value="">Select...</option>
              <option value="0-12">0-12</option>
              <option value="13-18">13-18</option>
              <option value="19-40">19-40</option>
              <option value="41-60">41-60</option>
              <option value="61+">61+</option>
            </select>
          </div>

          <div style={styles.field}>
            <label>Gender:</label>
            <select
              value={gender}
              onChange={(e) => setGender(e.target.value)}
              style={styles.select}
            >
              <option value="">Select...</option>
              <option value="Male">Male</option>
              <option value="Female">Female</option>
              <option value="Other">Other</option>
            </select>
          </div>

          <button type="submit" style={styles.button}>Submit</button>
        </form>
      ) : (
        <div style={styles.resultBox}>
          <h2>✅ Assessment Submitted!</h2>
          <p><strong>Age Group:</strong> {ageGroup}</p>
          <p><strong>Gender:</strong> {gender}</p>
          <p>Thank you, {username}, for completing the test!</p>
        </div>
      )}
    </div>
  );
}

// Inline CSS styles for simplicity
const styles = {
  container: {
    maxWidth: '500px',
    margin: '50px auto',
    padding: '20px',
    textAlign: 'center',
    border: '2px solid #10b981',
    borderRadius: '12px',
    backgroundColor: '#f9fafb',
    boxShadow: '0 4px 8px rgba(0,0,0,0.1)',
  },
  heading: {
    color: '#0f766e',
  },
  text: {
    marginBottom: '20px',
  },
  form: {
    display: 'flex',
    flexDirection: 'column',
    gap: '15px',
  },
  field: {
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'flex-start',
    fontSize: '16px',
  },
  select: {
    width: '100%',
    padding: '8px',
    borderRadius: '6px',
    border: '1px solid #ccc',
  },
  button: {
    padding: '10px 20px',
    backgroundColor: '#10b981',
    color: '#fff',
    border: 'none',
    borderRadius: '6px',
    cursor: 'pointer',
    fontSize: '16px',
  },
  resultBox: {
    padding: '20px',
    backgroundColor: '#ecfdf5',
    borderRadius: '10px',
    color: '#065f46',
  }
};

export default HealthAssessment;
